UPDATE content_items SET title='Cô giáo', description='1. Tay phải nắm, ngón cái và ngón trỏ mở ra, nắm nhẹ vào tai (vị trí đeo khuyên tai). 2. Tay phải giống số tự nhiên "1", lòng bàn tay hướng sang trái, đầu ngón tay hướng lên trên, đặt bên phải, ngang tầm mặt, đưa tay sang phải đồng thời gập cổ tay ra - vào.', image_url='/images/pages/page_0120.png' WHERE content_id=5 AND title='Giáo viên';

UPDATE content_items SET description='Tay phải nắm, ngón cái và ngón trỏ tay phải cong lại giống chữ C, lòng bàn tay hướng vào trong, đặt chạm vào ngực trái, đưa nhẹ tay sang phải.', image_url='/images/pages/page_0120.png' WHERE content_id=5 AND title='Công nhân';

UPDATE content_items SET description='1. Tay phải giống chữ S, lòng bàn tay hướng vào trong, đặt gần ngực trái, đưa tay sang ngực phải. 2. Ngón cái và ngón trỏ của hai tay chạm vào nhau, các ngón khác nắm lại, lòng bàn tay úp, đặt trước ngực, giữ nguyên tay trái, đưa tay phải xuống dưới (2 lần).', image_url='/images/pages/page_0120.png' WHERE content_id=5 AND title='Nông dân';

UPDATE content_items SET description='Tay phải giống số tự nhiên "1", lòng bàn tay úp, đầu ngón tay hướng sang trái, đặt sát giữa trán, đưa tay theo hình dấu "+".', image_url='/images/pages/page_0120.png' WHERE content_id=5 AND title='Bác sĩ';

UPDATE content_items SET description='Tay phải giống số tự nhiên "1", lòng bàn tay hướng vào trong, đầu ngón tay hướng vào trong, đưa chạm đầu ngón trỏ vào bắp tay trái.', image_url='/images/pages/page_0121.png' WHERE content_id=5 AND title='Y tá';

UPDATE content_items SET description='Tay phải giống chữ U, lòng bàn tay hướng sang trái, đặt chạm vào trán bên phải, đưa tay xuống chạm vào vai phải.', image_url='/images/pages/page_0121.png' WHERE content_id=5 AND title='Bộ đội';

UPDATE content_items SET description='1+2. Tay phải giống chữ C, lòng bàn tay hướng sang trái, đặt chạm vào giữa trán, sau đó thay đổi tay giống chữ A.', image_url='/images/pages/page_0121.png' WHERE content_id=5 AND title='Công an';

UPDATE content_items SET description='1. Tay trái khép, lòng bàn tay úp, đầu ngón tay hướng sang phải, đặt trước ngực. Tay phải khép, lòng bàn tay hướng sang trái, đầu ngón tay hướng về phía trước, đặt chạm trên mu bàn tay trái, đưa tay phải lên, xuống (2 lần). 2. Hai tay giống chữ C, lòng bàn tay hướng vào nhau, đặt trước hai mắt, đưa tay lên - xuống về phía trước (2 lần).', image_url='/images/pages/page_0121.png' WHERE content_id=5 AND title='Thợ xây';

